from scipy.stats import norm
import numpy as np

def d1_d2(S, K, T, r, sigma):
    d1 = (np.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
    return d1, d1 - sigma * np.sqrt(T)

def charm_analytic(S, K, T, r, sigma):
    d1, d2 = d1_d2(S, K, T, r, sigma)
    return norm.pdf(d1) * (d2 / (2 * T) - r / (sigma * np.sqrt(T)))

def bs_delta(S, K, T, r, sigma):
    d1, _ = d1_d2(S, K, T, r, sigma)
    return norm.cdf(d1)

# Finite-difference check: bump T by a small amount and re-difference Delta
S, K, r, sigma = 26500, 26500, 0.065, 0.132
T = 7 / 365
h = 1e-5

# Delta increases with calendar time t, i.e. as T decreases, so flip the sign of dT
charm_fd = -(bs_delta(S, K, T + h, r, sigma) - bs_delta(S, K, T - h, r, sigma)) / (2 * h)

print(f"Charm (per year), analytic: {charm_analytic(S, K, T, r, sigma):.4f}")
print(f"Charm (per year), finite-diff: {charm_fd:.4f}")
print(f"Charm per day: {charm_analytic(S, K, T, r, sigma) / 365:.5f}")
